    @if ($packages->isNotEmpty())<script>(()=>{const radios=[...document.querySelectorAll('input[name="package_id"]')],addons=[...document.querySelectorAll('input[name="addons[]"]')],total=document.getElementById('quote-total'),currency=@json($packages->first()->currency);const update=()=>{const p=radios.find(x=>x.checked);addons.forEach(x=>{x.closest('.addon').hidden=!!p&&x.dataset.package!==p.value;if(x.closest('.addon').hidden)x.checked=false});const cents=(p?Number(p.dataset.price):0)+addons.filter(x=>x.checked).reduce((sum,x)=>sum+Number(x.dataset.price),0);total.textContent=p?`${currency} ${(cents/100).toFixed(2)}`:'—'};radios.concat(addons).forEach(x=>x.addEventListener('change',update));update()})();</script>@endif
